sp_EditarCategoriaProduto	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_EditarCategoriaProduto`(\n\n    IN p_idCategoria    INT,\n\n    IN p_nome           VARCHAR(70),\n\n    IN p_descricao      VARCHAR(50),\n\n    IN p_idCategoriaPai INT\n\n)\nBEGIN\n\n    UPDATE CategoriaProduto SET\n\n        Nome             = p_nome,\n\n        Descricao        = p_descricao,\n\n        categoria_pai_id = p_idCategoriaPai\n\n    WHERE idCategoriaProduto = p_idCategoria;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
